<?php foreach($entity['fields'] as $field=>$definition):
    if($field==='account_id'&&(!$access->can('users.view')||!$access->user['all_branches']))continue;
    $options=[];
    if($definition['type']==='ref'){
        $options[]=['id'=>'','name'=>$definition['required']?'Pilih '.$definition['label']:'Tidak ditetapkan'];
        foreach($choices[$field] as $choice)$options[]=['id'=>$choice['id'],'name'=>($choice['code']??'')!==''?$choice['code'].' — '.($choice['display_name']??$choice['name']):$choice['name']];
        if($mode==='edit'&&$field==='branch_id')$options=array_values(array_filter($options,fn($o)=>(string)$o['id']===(string)$values[$field]));
    }elseif($definition['type']==='select')foreach($definition['options'] as $code=>$name)$options[]=['id'=>$code,'name'=>$name];
    $type=match($definition['type']){'ref','select'=>'select','money'=>'text','date'=>'date',default=>$field==='email'?'email':($field==='address'?'textarea':'text')};
    $required=$definition['required']??false;if(in_array($key,['drivers','operators'],true)&&$field==='name')$required=false;
